export const fallbackNotLocked = {
  async test(ctrl, env) {
    // Test that one long running fallback does not block another one.
    const promises = [];
    promises.push(
      env.CACHE.read('aaa', async () => {
        await scheduler.wait(500);
        return { value: 'aaa' };
      })
    );
    promises.push(
      env.CACHE.read('bbb', async () => {
        return { value: 'bbb' };
      })
    );
